inline material::TileAt Lookup(const Case& c) {
    return [&c](int x,int y)->std::optional<material::Tile> {
        if(y<0 || y>=80 || (c.flat && (x<0 || x>=80))) {return {};}
        x=(x+80)%80;
        material::Tile tile{3,c.uniform,0,0};
        if(material::Point{{x,y}}==c.coord) {tile=c.center;}
        const auto matches=[&](const std::array<int,3>& field) {return field[2]>=0 && x==(c.coord[0]+field[0]+80)%80 && y==c.coord[1]+field[1];};
        if(matches(c.moisture)) {tile.moisture=static_cast<uint8_t>(c.moisture[2]);}
        if(matches(c.band)) {tile.band=static_cast<uint8_t>(c.band[2]);}
        if(matches(c.items)) {tile.items=static_cast<uint32_t>(c.items[2]);}
        return tile;
    };
}
